// One More Tile in miniature: a 30×16 corner of the real game, playable on the homepage,
// plus a self-playing replay for the project dialog. Plain JS, no dependencies.
// Same rules and colours as the game: every number counts the light tiles in its 3×3 block
// (itself included, never across a region border), and a finished region shows the painting.
(() => {
  // DATA:BEGIN (generated by tools/tile-board.js, do not edit by hand)
  const DATA = {
    reg: '',
    sol: '',
    clue: '',
    pal: ["#cb5e70","#94437e","#e17965","#f49a54","#aa6775","#673429","#9784b0","#553e60","#40314c","#603e44","#8b5559","#6c517a","#2f3626","#34452b","#ad6e5d","#491a26","#864d44","#6e2727","#9f3e31","#ccab85","#24101d","#3e4b29","#d24f8c","#bd59b0","#462d4c","#613d66","#745080"],
    art: ''
  };
  // DATA:END

  const W = 30, H = 16, N = W * H;
  const F = 4;                 // painting pixels per cell side: the art is 120×64
  const REVEAL_MS = 900;       // the game's cross-fade from stitches to painting
  // Regions already finished when the homepage board loads: the sky and the lake,
  // so the painting shows through but the castle and the ship are still to find.
  // Region ids come from the DATA block; re-check these after regenerating it.
  const START_REVEALED = [0, 2, 3, 4, 10, 13];

  // The game's canvas palette at its default hue (258)
  const C = {
    light: '#fdfcff', dark: '#463678', clue: '#473a6e', clueOnDark: '#ddd4f7', clueBad: '#d23c4e',
    grid: 'rgba(95,71,148,', edge: '#7b65b8', border: 'rgba(240,166,54,', hi: 'rgba(240,162,36,.22)', hiLine: 'rgba(240,162,36,.85)'
  };
  const TINTS = ['#c8bce6', '#bdb1dd', '#d1c6ec', '#c2b4d9', '#cabee0', '#b7addb', '#d6cdef'];

  const reg = [...DATA.reg].map(ch => parseInt(ch, 36));
  const sol = [...DATA.sol].map(Number);
  const R = Math.max(...reg) + 1;
  const cellsOf = Array.from({ length: R }, () => []);
  reg.forEach((r, i) => cellsOf[r].push(i));
  const nb = reg.map((r, i) => {
    const x = i % W, y = (i / W) | 0, a = [];
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
      const nx = x + dx, ny = y + dy, j = ny * W + nx;
      if (nx >= 0 && ny >= 0 && nx < W && ny < H && reg[j] === r) a.push(j);
    }
    return a;
  });
  const clue = [...DATA.clue].map((b, i) => b === '1' ? nb[i].reduce((a, j) => a + sol[j], 0) : -1);

  // Region tints: first tint no smaller-numbered neighbour uses, as the game does
  const tint = [];
  for (let r = 0; r < R; r++) {
    const used = new Set();
    for (const i of cellsOf[r]) for (const j of [i - 1, i + 1, i - W, i + W]) {
      if (j < 0 || j >= N || (j === i - 1 && i % W === 0) || (j === i + 1 && j % W === 0)) continue;
      if (reg[j] < r) used.add(tint[reg[j]]);
    }
    tint[r] = TINTS.find(t => !used.has(t)) || TINTS[r % TINTS.length];
  }

  // The replay opens on the smallest region, so the first reveal comes quickly,
  // then works top to bottom: sky first, the lake last
  const centre = r => cellsOf[r].reduce((a, i) => [a[0] + i % W, a[1] + ((i / W) | 0)], [0, 0]).map(v => v / cellsOf[r].length);
  const ORDER = [...Array(R).keys()].sort((a, b) => centre(a)[1] - centre(b)[1] || centre(a)[0] - centre(b)[0]);
  const smallest = ORDER.reduce((m, r) => cellsOf[r].length < cellsOf[m].length ? r : m);
  ORDER.splice(ORDER.indexOf(smallest), 1);
  ORDER.unshift(smallest);

  let artCanvas = null;
  function art() {
    if (artCanvas) return artCanvas;
    const KEYS = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    const pal = DATA.pal.map(h => [1, 3, 5].map(k => parseInt(h.slice(k, k + 2), 16)));
    artCanvas = document.createElement('canvas');
    artCanvas.width = W * F; artCanvas.height = H * F;
    const g = artCanvas.getContext('2d');
    const img = g.createImageData(W * F, H * F);
    for (let p = 0; p < DATA.art.length; p++) img.data.set([...pal[KEYS.indexOf(DATA.art[p])], 255], p * 4);
    g.putImageData(img, 0, 0);
    return artCanvas;
  }

  // The next forced move. A wrong tile comes first; otherwise the clue whose count
  // forces its open tiles, nearest to `near`. `only` limits the search to one region.
  // Plain neighbour counting always finds one: the board is built to solve that way.
  function nextMove(st, done, only, near) {
    const open = i => !done[reg[i]] && (only == null || reg[i] === only);
    for (let i = 0; i < N; i++) if (open(i) && st[i] && st[i] !== (sol[i] ? 1 : 2)) return { wrong: i };
    let best = null, bestD = Infinity;
    for (let i = 0; i < N; i++) {
      if (clue[i] < 0 || !open(i)) continue;
      let L = 0; const U = [];
      for (const j of nb[i]) { if (st[j] === 1) L++; else if (!st[j]) U.push(j); }
      if (!U.length) continue;
      const v = L === clue[i] ? 2 : L + U.length === clue[i] ? 1 : 0;
      if (!v) continue;
      const d = near == null || near < 0 ? 0 : Math.hypot(i % W - near % W, ((i / W) | 0) - ((near / W) | 0));
      if (d < bestD) { best = { clue: i, cells: U, v }; bestD = d; }
    }
    return best;
  }

  const STOP = Symbol('stop');
  const mmss = ms => { const t = Math.floor(ms / 1000); return String(Math.floor(t / 60)).padStart(2, '0') + ':' + String(t % 60).padStart(2, '0'); };

  function TileBoard(host, opts = {}) {
    const demo = !!opts.demo;
    const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const coarse = matchMedia('(pointer: coarse)').matches;
    const st = new Uint8Array(N);                  // 0 open, 1 light, 2 dark
    const done = new Array(R).fill(false), doneAt = new Array(R).fill(-Infinity);

    host.classList.add('omt-host');
    const root = document.createElement('div');
    root.className = 'omt';
    root.innerHTML =
      '<div class="omt__bar">' +
        '<span class="omt__logo">One More Tile</span>' +
        '<span class="omt__status"><b class="omt__pct">0%</b><span class="omt__map">Castle</span><span class="omt__time">00:00</span></span>' +
        (demo
          ? '<span class="omt__live"><i></i>Replay</span>'
          : '<button type="button" class="omt__btn omt__hint">Hint</button><button type="button" class="omt__btn omt__reset" title="Start over" aria-label="Start over">&#8634;</button>') +
        '<span class="omt__progress"><i></i></span>' +
      '</div>' +
      '<div class="omt__stage"><canvas class="omt__canvas"></canvas></div>' +
      '<p class="omt__tip" aria-live="polite"></p>';
    host.replaceChildren(root);
    const q = s => root.querySelector(s);
    const stage = q('.omt__stage'), canvas = q('.omt__canvas'), tip = q('.omt__tip');
    const pctEl = q('.omt__pct'), barEl = q('.omt__progress i'), timeEl = q('.omt__time');
    const ctx = canvas.getContext('2d');

    const RULE = 'Each number counts the light tiles in its 3×3 block.';
    const HOWTO = coarse ? 'Tap a tile to cycle light, dark, empty.' : 'Click for light, right-click for dark.';
    const say = html => { tip.innerHTML = html; };

    // ---------- layout ----------
    let s = 10, ox = 0, oy = 0, cw = 0, ch = 0, dpr = 1;
    function layout() {
      const pad = 8;
      const narrow = !demo && host.clientWidth < 560;
      host.classList.toggle('is-narrow', narrow);
      const sw = stage.clientWidth;
      let sh;
      if (narrow) {
        // Too small to tap at full width: keep tiles finger-sized and let the stage scroll sideways
        s = Math.max(17, (sw - 2 * pad) / W);
        sh = Math.ceil(H * s + 2 * pad);
        stage.style.height = sh + 'px';
      } else {
        stage.style.height = '';
        sh = stage.clientHeight;
        s = Math.max(4, Math.min((sw - 2 * pad) / W, (sh - 2 * pad) / H));
      }
      cw = Math.max(sw, Math.ceil(W * s + 2 * pad)); ch = sh;
      ox = Math.round((cw - W * s) / 2); oy = Math.round((ch - H * s) / 2);
      dpr = window.devicePixelRatio || 1;
      canvas.width = Math.round(cw * dpr); canvas.height = Math.round(ch * dpr);
      canvas.style.width = cw + 'px'; canvas.style.height = ch + 'px';
      schedule();
    }
    const cellAt = e => {
      const r = canvas.getBoundingClientRect();
      const x = Math.floor((e.clientX - r.left - ox) / s), y = Math.floor((e.clientY - r.top - oy) / s);
      return x >= 0 && y >= 0 && x < W && y < H ? y * W + x : -1;
    };

    // ---------- state ----------
    let cur = -1;                  // the working cell: 3×3 highlight
    let hintCells = [], hintAt = 0, wrong = -1;
    let t0 = 0, tEnd = 0;          // timer
    let finAt = -1;                // whole canvas done: borders and grid fade away
    let pointer = null;            // replay cursor {x, y, fx, fy, tx, ty, at, dur, clickAt}

    function progress() {
      const n = cellsOf.reduce((a, c, r) => a + (done[r] ? c.length : 0), 0);
      const pct = Math.round(n / N * 100) + '%';
      pctEl.textContent = pct; barEl.style.width = pct;
      return n === N;
    }
    function reveal(r, instant) {
      done[r] = true;
      doneAt[r] = instant || reduce ? -Infinity : performance.now();
      for (const j of cellsOf[r]) st[j] = sol[j] ? 1 : 2;
    }
    // A region is finished once its light tiles are all stitched and nothing else is
    function check(r) {
      if (done[r] || !cellsOf[r].every(j => sol[j] ? st[j] === 1 : st[j] !== 1)) return;
      reveal(r);
      hintCells = hintCells.filter(j => reg[j] !== r);
      if (progress()) {
        tEnd = performance.now(); finAt = reduce ? -Infinity : performance.now();
        say(demo ? '<b>Canvas complete.</b> The full game has nine paintings, each about sixteen times this size.'
                 : `<b>Canvas complete in ${mmss(tEnd - t0)}.</b> The full game has nine paintings, each about sixteen times this size.`);
      } else if (!demo) {
        const left = done.filter(d => !d).length;
        say(`<b>Region revealed.</b> ${left} to go. ${RULE}`);
      }
    }
    function set(i, v) {
      if (i < 0 || done[reg[i]] || st[i] === v) return;
      if (!t0) t0 = performance.now();
      st[i] = v;
      if (i === wrong) wrong = -1;
      hintCells = hintCells.filter(j => !st[j]);
      check(reg[i]);
      schedule();
    }
    function reset(revealed = []) {
      st.fill(0); done.fill(false); doneAt.fill(-Infinity);
      for (const r of revealed) reveal(r, true);
      cur = -1; hintCells = []; wrong = -1; t0 = 0; tEnd = 0; finAt = -1;
      progress(); schedule();
    }

    // ---------- drawing ----------
    let raf = 0, alive = true, visible = true;
    function schedule() { if (!raf && alive) raf = requestAnimationFrame(frame); }
    function frame() {
      raf = 0;
      if (!host.isConnected) { destroy(); return; }
      // performance.now(), not the rAF timestamp: that can be older than the doneAt a stitch just set
      if (draw(performance.now())) schedule();
    }
    function draw(now) {
      const g = ctx;
      let busy = false;
      g.setTransform(dpr, 0, 0, dpr, 0, 0);
      g.clearRect(0, 0, cw, ch);
      g.imageSmoothingEnabled = false;
      const fin = finAt < 0 ? 0 : Math.min(1, (now - finAt) / 800);
      if (fin > 0 && fin < 1) busy = true;
      g.fillStyle = C.edge;
      g.globalAlpha = 1 - fin;
      g.fillRect(ox - 3, oy - 3, W * s + 6, H * s + 6);
      g.globalAlpha = 1;

      // cells: stitches, then the painting fading in over finished regions
      const A = art();
      for (let i = 0; i < N; i++) {
        const x = i % W, y = (i / W) | 0, px = ox + x * s, py = oy + y * s, r = reg[i];
        const f = done[r] ? Math.max(0, Math.min(1, (now - doneAt[r]) / REVEAL_MS)) : 0;
        if (done[r] && f < 1) busy = true;
        if (f < 1) {
          g.fillStyle = st[i] === 1 ? C.light : st[i] === 2 ? C.dark : tint[r];
          g.fillRect(px, py, s + .5, s + .5);
        }
        if (f > 0) {
          if (f < 1) g.globalAlpha = f;
          g.drawImage(A, x * F, y * F, F, F, px, py, s + .5, s + .5);
          g.globalAlpha = 1;
        }
      }

      // grid
      if (s >= 5 && fin < 1) {
        g.strokeStyle = C.grid + (.18 * (1 - fin)) + ')';
        g.lineWidth = 1;
        g.beginPath();
        for (let x = 0; x <= W; x++) { g.moveTo(ox + x * s, oy); g.lineTo(ox + x * s, oy + H * s); }
        for (let y = 0; y <= H; y++) { g.moveTo(ox, oy + y * s); g.lineTo(ox + W * s, oy + y * s); }
        g.stroke();
      }

      // the working cell's 3×3: the tiles a clue there actually counts
      if (cur >= 0 && !done[reg[cur]]) {
        g.fillStyle = C.hi;
        for (const j of nb[cur]) g.fillRect(ox + (j % W) * s, oy + ((j / W) | 0) * s, s + .5, s + .5);
        g.strokeStyle = C.hiLine;
        g.lineWidth = Math.max(1.5, s * .1);
        g.strokeRect(ox + (cur % W) * s + .6, oy + ((cur / W) | 0) * s + .6, s - 1.2, s - 1.2);
      }

      // clues
      if (s >= 8) {
        g.textAlign = 'center'; g.textBaseline = 'middle';
        g.font = `600 ${Math.floor(s * .58)}px "Segoe UI", system-ui, sans-serif`;
        for (let i = 0; i < N; i++) {
          const c = clue[i];
          if (c < 0 || done[reg[i]]) continue;
          let L = 0, U = 0;
          for (const j of nb[i]) { if (st[j] === 1) L++; else if (!st[j]) U++; }
          const bad = c - L < 0 || c - L > U;
          g.globalAlpha = U === 0 && L === c ? .28 : 1;
          g.fillStyle = bad ? C.clueBad : st[i] === 2 ? C.clueOnDark : C.clue;
          g.fillText(c, ox + (i % W + .5) * s, oy + (((i / W) | 0) + .55) * s);
        }
        g.globalAlpha = 1;
      }

      // region borders
      if (fin < 1) {
        g.strokeStyle = C.border + (.95 * (1 - fin)) + ')';
        g.lineWidth = Math.max(2, s * .13);
        g.beginPath();
        for (let i = 0; i < N; i++) {
          const x = i % W, y = (i / W) | 0, px = ox + x * s, py = oy + y * s;
          if (x < W - 1 && reg[i] !== reg[i + 1]) { g.moveTo(px + s, py); g.lineTo(px + s, py + s); }
          if (y < H - 1 && reg[i] !== reg[i + W]) { g.moveTo(px, py + s); g.lineTo(px + s, py + s); }
        }
        g.stroke();
      }

      // hint: pulse the tiles it forces; a wrong tile gets a red ring
      if (hintCells.length || wrong >= 0) {
        const pulse = reduce ? 1 : .55 + .45 * Math.sin((now - hintAt) / 160);
        g.lineWidth = Math.max(2, s * .14);
        g.strokeStyle = `rgba(196,93,255,${pulse})`;
        for (const j of hintCells) g.strokeRect(ox + (j % W) * s + 1.5, oy + ((j / W) | 0) * s + 1.5, s - 3, s - 3);
        if (wrong >= 0) {
          g.strokeStyle = `rgba(210,60,78,${pulse})`;
          g.strokeRect(ox + (wrong % W) * s + 1.5, oy + ((wrong / W) | 0) * s + 1.5, s - 3, s - 3);
        }
        if (!reduce) busy = true;
      }

      // replay cursor
      if (pointer) {
        const p = pointer, k = Math.min(1, (now - p.at) / p.dur), e = 1 - Math.pow(1 - k, 3);
        if (k < 1) busy = true;
        p.x = p.fx + (p.tx - p.fx) * e; p.y = p.fy + (p.ty - p.fy) * e;
        const c = Math.min(1, (now - p.clickAt) / 320);
        if (c < 1) {
          busy = true;
          g.strokeStyle = `rgba(240,162,36,${.9 * (1 - c)})`;
          g.lineWidth = 2;
          g.beginPath(); g.arc(p.x, p.y, s * (.3 + .7 * c), 0, Math.PI * 2); g.stroke();
        }
        g.save();
        g.translate(p.x, p.y);
        g.beginPath();
        g.moveTo(0, 0); g.lineTo(0, 16); g.lineTo(4.2, 12.2); g.lineTo(7.2, 18.6); g.lineTo(9.8, 17.4); g.lineTo(6.9, 11.2); g.lineTo(12, 11.2);
        g.closePath();
        g.fillStyle = '#fff'; g.strokeStyle = '#2a1f4a'; g.lineWidth = 1.4; g.lineJoin = 'round';
        g.fill(); g.stroke();
        g.restore();
      }
      return busy;
    }

    // ---------- timer ----------
    const tick = setInterval(() => {
      if (!alive) return;
      timeEl.textContent = mmss(t0 ? (tEnd || performance.now()) - t0 : 0);
    }, 500);

    // ---------- visibility ----------
    const io = new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible) schedule(); });
    io.observe(host);
    const ro = new ResizeObserver(layout);
    ro.observe(stage);

    function destroy() {
      alive = false;
      cancelAnimationFrame(raf); raf = 0;
      clearInterval(tick); io.disconnect(); ro.disconnect();
    }

    if (demo) runReplay(); else play();
    return { destroy };

    // ---------- playable board ----------
    function play() {
      reset(START_REVEALED);
      say(`<b>Try it.</b> ${RULE} ${HOWTO}`);
      canvas.tabIndex = 0;
      canvas.setAttribute('role', 'application');
      canvas.setAttribute('aria-label', 'One More Tile puzzle, 30 by 16 tiles. Arrow keys move, Space stitches a tile light, X marks it dark, H gives a hint.');

      let paint = -1, lastType = 'mouse';
      canvas.addEventListener('contextmenu', e => e.preventDefault());
      canvas.addEventListener('pointerdown', e => {
        lastType = e.pointerType;
        if (e.pointerType !== 'mouse') return;       // touch and pen act on click, so scrolling the page never stitches
        const i = cellAt(e);
        if (i < 0 || done[reg[i]]) return;
        if (e.button === 0) paint = st[i] === 1 ? 0 : 1;
        else if (e.button === 2) paint = st[i] === 2 ? 0 : 2;
        else return;
        e.preventDefault();
        canvas.focus({ preventScroll: true });
        canvas.setPointerCapture(e.pointerId);
        cur = i; set(i, paint);
      });
      canvas.addEventListener('pointermove', e => {
        if (e.pointerType !== 'mouse') return;
        const i = cellAt(e);
        if (i !== cur) { cur = i; schedule(); }
        if (paint >= 0 && e.buttons) set(i, paint);  // drag to stitch a run of tiles
      });
      const lift = () => { paint = -1; };
      canvas.addEventListener('pointerup', lift);
      canvas.addEventListener('pointercancel', lift);
      canvas.addEventListener('pointerleave', () => { if (paint < 0 && document.activeElement !== canvas) { cur = -1; schedule(); } });
      canvas.addEventListener('click', e => {
        if (lastType === 'mouse') return;
        const i = cellAt(e);
        if (i < 0 || done[reg[i]]) return;
        cur = i; set(i, (st[i] + 1) % 3); schedule();
      });
      canvas.addEventListener('keydown', e => {
        const k = e.key;
        const move = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -W, ArrowDown: W }[k];
        if (move) {
          if (cur < 0) cur = st.findIndex((v, i) => !done[reg[i]]);
          else {
            const x = cur % W + (move === -1 ? -1 : move === 1 ? 1 : 0), y = ((cur / W) | 0) + (move === -W ? -1 : move === W ? 1 : 0);
            if (x >= 0 && y >= 0 && x < W && y < H) cur = y * W + x;
          }
        } else if (cur >= 0 && (k === ' ' || k === 'Enter')) set(cur, st[cur] === 1 ? 0 : 1);
        else if (cur >= 0 && (k === 'x' || k === 'X')) set(cur, st[cur] === 2 ? 0 : 2);
        else if (k === 'h' || k === 'H') hint();
        else return;
        e.preventDefault();
        schedule();
      });
      canvas.addEventListener('blur', () => { if (paint < 0) { cur = -1; schedule(); } });

      q('.omt__hint').addEventListener('click', hint);
      q('.omt__reset').addEventListener('click', () => { reset(START_REVEALED); say(`<b>Fresh canvas.</b> ${RULE} ${HOWTO}`); });
    }

    // Point at a forced move near where you're working and say why it's forced
    function hint() {
      const m = nextMove(st, done, null, cur);
      if (!m) return;
      hintAt = performance.now();
      if (m.wrong != null) {
        wrong = m.wrong; hintCells = []; cur = m.wrong;
        say(`<b>This tile is wrong.</b> It should be ${sol[m.wrong] ? 'light' : 'dark'}.`);
      } else {
        const c = clue[m.clue], n = m.cells.length;
        wrong = -1; hintCells = m.cells; cur = m.clue;
        say(m.v === 2
          ? (c === 0 ? '<b>A 0 counts no light tiles,</b> so its whole block is dark.'
                     : `<b>This ${c} already sees ${c} light tile${c === 1 ? '' : 's'},</b> so the ${n === 1 ? 'open tile' : n + ' open tiles'} next to it ${n === 1 ? 'is' : 'are'} dark.`)
          : `<b>This ${c} needs ${n === 1 ? 'its last open tile' : 'all ' + n + ' open tiles'} to reach ${c},</b> so ${n === 1 ? 'it is' : 'they are'} light.`);
      }
      schedule();
    }

    // ---------- replay ----------
    // Solves the canvas region by region with the same forced moves a hint would show,
    // slow at first so you can follow the counting, then faster. Pauses off screen.
    async function runReplay() {
      canvas.setAttribute('role', 'img');
      canvas.setAttribute('aria-label', 'Replay of One More Tile being solved: tiles are stitched light or dark by counting, and each finished region reveals part of a pixel-art castle by a lake.');
      if (reduce) {
        // One still frame mid-game instead of motion
        reset(ORDER.slice(0, 8));
        const r = ORDER[8];
        for (let k = 0; k < 4; k++) { const m = nextMove(st, done, r, cur); if (!m || m.wrong != null) break; m.cells.forEach(j => { st[j] = m.v; }); cur = m.clue; }
        say(RULE);
        return;
      }
      const wait = async ms => {
        await new Promise(res => setTimeout(res, ms));
        while (alive && host.isConnected && (!visible || document.hidden)) await new Promise(res => setTimeout(res, 250));
        if (!alive || !host.isConnected) { destroy(); throw STOP; }
      };
      const centerOf = i => [ox + (i % W + .5) * s, oy + (((i / W) | 0) + .5) * s];
      const glide = (i, ms) => {
        const [tx, ty] = centerOf(i);
        if (!pointer) pointer = { x: cw / 2, y: ch + 20, clickAt: -1e9 };
        Object.assign(pointer, { fx: pointer.x, fy: pointer.y, tx, ty, at: performance.now(), dur: ms });
        schedule();
        return wait(ms);
      };
      try {
        for (;;) {
          reset(); pointer = null;
          canvas.style.opacity = 1;
          say(RULE);
          await wait(700);
          t0 = performance.now();
          let n = 0;
          for (const r of ORDER) {
            const pace = Math.max(.18, .8 - n++ * .15);
            for (let m; !done[r] && (m = nextMove(st, done, r, cur));) {
              await glide(m.clue, 200 * pace);
              cur = m.clue; schedule();
              await wait(220 * pace);
              for (const j of m.cells) {
                await glide(j, 45 * pace + 15);
                pointer.clickAt = performance.now();
                set(j, m.v);
                await wait(25 * pace);
              }
            }
            cur = -1; schedule();
            await wait(REVEAL_MS * .7 * pace + 150);
          }
          pointer = null; schedule();
          await wait(4800);
          canvas.style.opacity = 0;
          await wait(600);
        }
      } catch (e) { if (e !== STOP) throw e; }
    }
  }

  window.TileBoard = TileBoard;
  document.querySelectorAll('[data-omt]').forEach(el => TileBoard(el));
})();
